89	/**
90	 * Event-Driven Orchestrator for Tool Execution.
91	 * Coordinates execution via state updates and event listening.
92	 */
93	export class Scheduler {
94	  // Tracks which MessageBus instances have the legacy listener attached to prevent duplicates.
95	  private static subscribedMessageBuses = new WeakSet<MessageBus>();
96	
97	  private readonly state: SchedulerStateManager;
98	  private readonly executor: ToolExecutor;
99	  private readonly modifier: ToolModificationHandler;
100	  private readonly config: Config;
101	  private readonly context: AgentLoopContext;
102	  private readonly messageBus: MessageBus;
103	  private readonly getPreferredEditor: () => EditorType | undefined;
104	  private readonly schedulerId: string;
105	  private readonly parentCallId?: string;
106	  private readonly onWaitingForConfirmation?: (waiting: boolean) => void;
107	
108	  private isProcessing = false;
109	  private isCancelling = false;
110	  private readonly requestQueue: SchedulerQueueItem[] = [];
111	
112	  constructor(options: SchedulerOptions) {
113	    this.config = options.config;
114	    this.context = options.config;
115	    this.messageBus = options.messageBus ?? this.context.messageBus;
116	    this.getPreferredEditor = options.getPreferredEditor;
117	    this.schedulerId = options.schedulerId;
118	    this.parentCallId = options.parentCallId;
119	    this.onWaitingForConfirmation = options.onWaitingForConfirmation;
120	    this.state = new SchedulerStateManager(
121	      this.messageBus,
122	      this.schedulerId,
123	      (call) => logToolCall(this.config, new ToolCallEvent(call)),
124	    );
125	    this.executor = new ToolExecutor(this.config, this.context);
126	    this.modifier = new ToolModificationHandler();
127	
128	    this.setupMessageBusListener(this.messageBus);
129	
130	    coreEvents.on(CoreEvent.McpProgress, this.handleMcpProgress);
131	  }
132	
133	  dispose(): void {
134	    coreEvents.off(CoreEvent.McpProgress, this.handleMcpProgress);
135	  }
136	
137	  private readonly handleMcpProgress = (payload: McpProgressPayload) => {
138	    const { callId } = payload;
139	
140	    const call = this.state.getToolCall(callId);
141	    if (!call || call.status !== CoreToolCallStatus.Executing) {
142	      return;
143	    }
144	
145	    const validTotal =
146	      payload.total !== undefined &&
147	      Number.isFinite(payload.total) &&
148	      payload.total > 0
149	        ? payload.total
150	        : undefined;
151	
152	    this.state.updateStatus(callId, CoreToolCallStatus.Executing, {
153	      progressMessage: payload.message,
154	      progressPercent: validTotal
155	        ? Math.min(100, (payload.progress / validTotal) * 100)
156	        : undefined,
157	      progress: payload.progress,
158	      progressTotal: validTotal,
159	    });
160	  };
