162	  private setupMessageBusListener(messageBus: MessageBus): void {
163	    if (Scheduler.subscribedMessageBuses.has(messageBus)) {
164	      return;
165	    }
166	
167	    // TODO: Optimize policy checks. Currently, tools check policy via
168	    // MessageBus even though the Scheduler already checked it.
169	    messageBus.subscribe(
170	      MessageBusType.TOOL_CONFIRMATION_REQUEST,
171	      async (request: ToolConfirmationRequest) => {
172	        await messageBus.publish({
173	          type: MessageBusType.TOOL_CONFIRMATION_RESPONSE,
174	          correlationId: request.correlationId,
175	          confirmed: false,
176	          requiresUserConfirmation: true,
177	        });
178	      },
179	    );
180	
181	    Scheduler.subscribedMessageBuses.add(messageBus);
182	  }
