46	export interface ToolExecutionContext {
47	  call: ToolCall;
48	  signal: AbortSignal;
49	  outputUpdateHandler?: (callId: string, output: ToolLiveOutput) => void;
50	  onUpdateToolCall: (updatedCall: ToolCall) => void;
51	}
