53	export class ToolExecutor {
54	  constructor(
55	    private readonly config: Config,
56	    private readonly context: AgentLoopContext,
57	  ) {}
58	
59	  async execute(context: ToolExecutionContext): Promise<CompletedToolCall> {
60	    const { call, signal, outputUpdateHandler, onUpdateToolCall } = context;
61	    const { request } = call;
62	    const toolName = request.name;
63	    const callId = request.callId;
64	
65	    if (!('tool' in call) || !call.tool || !('invocation' in call)) {
66	      throw new Error(
67	        `Cannot execute tool call ${callId}: Tool or Invocation missing.`,
68	      );
69	    }
70	    const { tool, invocation } = call;
71	
72	    // Setup live output handling
73	    const liveOutputCallback =
74	      tool.canUpdateOutput && outputUpdateHandler
75	        ? (outputChunk: ToolLiveOutput) => {
76	            outputUpdateHandler(callId, outputChunk);
77	          }
78	        : undefined;
79	
80	    const shellExecutionConfig = this.config.getShellExecutionConfig();
81	
82	    return runInDevTraceSpan(
83	      {
84	        operation: GeminiCliOperation.ToolCall,
85	        attributes: {
86	          [GEN_AI_TOOL_NAME]: toolName,
87	          [GEN_AI_TOOL_CALL_ID]: callId,
88	          [GEN_AI_TOOL_DESCRIPTION]: tool.description,
89	        },
90	      },
91	      async ({ metadata: spanMetadata }) => {
92	        spanMetadata.input = request;
93	
94	        let completedToolCall: CompletedToolCall;
95	
96	        try {
97	          let promise: Promise<ToolResult>;
98	          if (invocation instanceof ShellToolInvocation) {
99	            const setPidCallback = (pid: number) => {
100	              const executingCall: ExecutingToolCall = {
101	                ...call,
102	                status: CoreToolCallStatus.Executing,
103	                tool,
104	                invocation,
105	                pid,
106	                startTime: 'startTime' in call ? call.startTime : undefined,
107	              };
108	              onUpdateToolCall(executingCall);
109	            };
110	            promise = executeToolWithHooks(
111	              invocation,
112	              toolName,
113	              signal,
114	              tool,
115	              liveOutputCallback,
116	              shellExecutionConfig,
117	              setPidCallback,
118	              this.config,
119	              request.originalRequestName,
120	            );
121	          } else {
122	            promise = executeToolWithHooks(
123	              invocation,
124	              toolName,
125	              signal,
126	              tool,
127	              liveOutputCallback,
128	              shellExecutionConfig,
129	              undefined,
130	              this.config,
131	              request.originalRequestName,
132	            );
133	          }
134	
135	          const toolResult: ToolResult = await promise;
136	
137	          if (signal.aborted) {
138	            completedToolCall = await this.createCancelledResult(
139	              call,
140	              'User cancelled tool execution.',
141	              toolResult,
142	            );
143	          } else if (toolResult.error === undefined) {
144	            completedToolCall = await this.createSuccessResult(
145	              call,
146	              toolResult,
147	            );
148	          } else {
149	            const displayText =
150	              typeof toolResult.returnDisplay === 'string'
151	                ? toolResult.returnDisplay
152	                : undefined;
153	            completedToolCall = this.createErrorResult(
154	              call,
155	              new Error(toolResult.error.message),
156	              toolResult.error.type,
157	              displayText,
158	              toolResult.tailToolCallRequest,
159	            );
160	          }
161	        } catch (executionError: unknown) {
162	          spanMetadata.error = executionError;
163	          const abortedByError =
164	            isAbortError(executionError) ||
165	            (executionError instanceof Error &&
166	              executionError.message.includes('Operation cancelled by user'));
167	
168	          if (signal.aborted || abortedByError) {
169	            completedToolCall = await this.createCancelledResult(
170	              call,
171	              isAbortError(executionError)
172	                ? 'Operation cancelled.'
173	                : 'User cancelled tool execution.',
174	            );
175	          } else {
176	            const error =
177	              executionError instanceof Error
178	                ? executionError
179	                : new Error(String(executionError));
180	            completedToolCall = this.createErrorResult(
